const events: number[] = [];
export async function compute(value: number): Promise<number> { try { return value ? await Promise.resolve(value + 1) : await Promise.resolve(0); } finally { events.push(1); } }
const arrow = async (value: number): Promise<number> => { return await compute(value); };
export const result: Promise<number> = arrow(41);

